fn abs(x: f32) -> f32 {
    if x < 0.0 { -x } else { x }
}

fn sqrt(x: f32) -> f32 with Mut {
    // Newton-Raphson approximation
    var guess = x / 2.0
    for i in 0..10 {
        guess = (guess + x / guess) / 2.0
    }
    guess
}

